package pl.kinowo

import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * The committed Baseline Profile — generated by the :baselineprofile module's
 * BaselineProfileGenerator and merged into `main`, so every release build ships
 * it as assets/dexopt/baseline.prof — covers the app's own code along the
 * critical journey (cold start → poster grid → scroll → film detail), not just
 * the profiles the libraries bundle. Regenerate with
 * `./gradlew :app:generateBaselineProfile` on an emulator (API 33+).
 */
class BaselineProfileTest {

    private val profile = File("src/main/generated/baselineProfiles/baseline-prof.txt")

    @Test
    fun theProfileCoversTheColdStartToFilmDetailJourney() {
        assertTrue("no Baseline Profile at $profile — run ./gradlew :app:generateBaselineProfile", profile.isFile)
        val rules = profile.readText()
        for (journeyClass in listOf(
            "pl/kinowo/KinowoApplication;",
            "pl/kinowo/MainActivity;",
            "pl/kinowo/ui/list/ListScreenKt",
            "pl/kinowo/ui/list/FilmCardKt",
            "pl/kinowo/ui/detail/DetailScreenKt",
            "pl/kinowo/net/KinowoApi;",
        )) assertTrue("the profile has no rules for $journeyClass", rules.contains("L$journeyClass"))
    }

    @Test
    fun theProfileNamesNoBenchmarkOnlyClass() {
        // BenchmarkApplication exists only in the nonMinified/benchmark builds the
        // generator drives; the profile ships in release, where it does not.
        assertFalse(profile.readText().contains("BenchmarkApplication"))
    }
}
